// Write public/assets/PROVENANCE.json: where every shipped asset came from.
//
// Each file under public/assets/ is compared by content (its git blob hash) with PrismarineJS/minecraft-assets, the
// mirror of Mojang's textures that scripts/download_assets.js and its neighbours fetch from:
//   - vanilla           identical to a file in minecraft-assets: Mojang's art, verified by hash;
//   - vanilla-derived   made from vanilla files by a script (the folder rules below say which);
//   - unknown-modified  has the name of a vanilla texture but different contents (edited, regenerated by a script, or
//                       taken from a version the mirror doesn't hold): needs a person to say which;
//   - unknown           no vanilla texture has its name: probably generated or drawn here, not yet confirmed.
// Entries a person has confirmed (`original`, `generated`, `third-party` or `vanilla-derived`) are kept when this runs
// again.
//
//   node scripts/seed-asset-provenance.mjs            reuse the cached upstream listings in .cache/asset-provenance/
//   node scripts/seed-asset-provenance.mjs --refresh  fetch them again (about 15 GitHub API calls, unauthenticated)
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, statSync } from 'node:fs';
import { join, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { contentsUrl, pin } from './dataLock.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const ASSETS = 'public/assets';
const OUT = join(root, ASSETS, 'PROVENANCE.json');
const CACHE = join(root, '.cache', 'asset-provenance');
// Trees are read by their object SHA (immutable); the repository comes from data-lock.json.
const API = `https://api.github.com/repos/${pin('minecraft-assets').repo}`;
// The versions the download scripts read first, then the newer ones the mirror holds.
const VERSIONS = ['1.21.4', '1.20.2', '1.19.1', '1.21.1', '1.21.5', '1.21.6', '1.21.7', '1.21.8', '1.21.9', '1.21.10',
  '1.21.11', '26.1', '1.18.1', '1.17.1', '1.16.4'];

/** Folders made wholesale by a script from vanilla files. */
export const FOLDER_RULES = {
  'packs/faithful_64x/': {
    source: 'vanilla-derived',
    by: 'scripts/generate-faithful-64x.py',
    note: 'Vanilla block textures from public/assets/blocks, upscaled to 64x64 with added detail. Not the Faithful community pack.',
  },
};

async function getJson(url) {
  const res = await fetch(url, { headers: { 'User-Agent': 'blockyland-provenance', Accept: 'application/vnd.github+json' } });
  if (!res.ok) throw new Error(`${url}: HTTP ${res.status} ${await res.text()}`);
  return res.json();
}

async function upstreamIndex(refresh) {
  mkdirSync(CACHE, { recursive: true });
  const dirsFile = join(CACHE, 'data-dirs.json');
  if (refresh || !existsSync(dirsFile)) writeFileSync(dirsFile, JSON.stringify(await getJson(contentsUrl('minecraft-assets', 'data'))));
  const dirs = new Map(JSON.parse(readFileSync(dirsFile, 'utf8')).map(e => [e.name, e.sha]));
  const bySha = new Map();
  const names = new Set();
  for (const version of VERSIONS) {
    const sha = dirs.get(version);
    if (!sha) continue;
    const file = join(CACHE, `${version}.json`);
    if (refresh || !existsSync(file)) writeFileSync(file, JSON.stringify(await getJson(`${API}/git/trees/${sha}?recursive=1`)));
    const tree = JSON.parse(readFileSync(file, 'utf8'));
    if (tree.truncated) console.warn(`  ${version}: the listing is truncated; some files may show as unknown`);
    for (const entry of tree.tree) {
      if (entry.type !== 'blob') continue;
      if (!bySha.has(entry.sha)) bySha.set(entry.sha, `${version}/${entry.path}`);
      names.add(basename(entry.path));
    }
  }
  return { bySha, names };
}

function localFiles(dir, base = dir, out = []) {
  for (const name of readdirSync(dir)) {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) localFiles(path, base, out);
    else out.push(path.slice(base.length + 1).split('\\').join('/'));
  }
  return out;
}

/** Git blob hashes of files, the same hashes GitHub's tree listing gives. */
function blobHashes(paths) {
  const out = execFileSync('git', ['hash-object', '--stdin-paths'], {
    cwd: root, input: paths.map(p => `${ASSETS}/${p}`).join('\n'), encoding: 'utf8', maxBuffer: 64 * 1024 * 1024,
  });
  return out.trim().split('\n');
}

async function main() {
  const refresh = process.argv.includes('--refresh');
  const previous = existsSync(OUT) ? JSON.parse(readFileSync(OUT, 'utf8')) : null;
  const confirmed = new Map();
  // Entries a person wrote by hand survive a rerun; the hash-derived ones are recomputed.
  const HAND_SOURCES = new Set(['original', 'generated', 'vanilla-derived', 'third-party']);
  for (const entry of previous?.entries ?? []) {
    if (HAND_SOURCES.has(entry.source)) for (const f of entry.files) confirmed.set(f, entry);
  }

  const { bySha, names } = await upstreamIndex(refresh);
  const files = localFiles(join(root, ASSETS)).filter(f => f !== 'PROVENANCE.json').sort();
  const loose = files.filter(f => !Object.keys(FOLDER_RULES).some(prefix => f.startsWith(prefix)));
  const hashes = blobHashes(loose);

  const groups = new Map();
  const add = (key, make, file) => {
    if (!groups.has(key)) groups.set(key, { ...make(), files: [] });
    groups.get(key).files.push(file);
  };
  loose.forEach((file, i) => {
    const kept = confirmed.get(file);
    if (kept) {
      // Keep every field a person wrote (by, from, license, note), grouped as they grouped it.
      const { files: _files, ...fields } = kept;
      return add(JSON.stringify(fields), () => fields, file);
    }
    const match = bySha.get(hashes[i]);
    if (match) {
      const version = match.split('/')[0];
      return add(`vanilla|${version}`, () => ({ source: 'vanilla', from: `PrismarineJS/minecraft-assets data/${version}` }), file);
    }
    if (names.has(basename(file))) {
      return add('unknown-modified', () => ({
        source: 'unknown-modified',
        note: 'Named like a vanilla texture, but not identical to any in PrismarineJS/minecraft-assets: edited, regenerated by a script, or from another version.',
      }), file);
    }
    add('unknown', () => ({ source: 'unknown', note: 'No vanilla texture has this name: probably generated or drawn here. Confirm as original or generated (with the script).' }), file);
  });

  const order = ['original', 'generated', 'third-party', 'vanilla-derived', 'vanilla', 'unknown-modified', 'unknown'];
  const entries = [...groups.values()].sort((a, b) => order.indexOf(a.source) - order.indexOf(b.source) || String(a.from).localeCompare(String(b.from)));
  for (const e of entries) for (const k of Object.keys(e)) if (e[k] === undefined) delete e[k];
  const doc = {
    about: 'Where each file under public/assets came from. Written by scripts/seed-asset-provenance.mjs and checked by scripts/checkPublicTree.mjs: every file must be covered by a folder rule or listed in an entry. Change "unknown" entries to "original" or "generated" (with "by": the script) once confirmed; reruns keep those.',
    sources: {
      original: 'Made for Blockyland by hand.',
      generated: 'Made by a script in this repository from no third-party art ("by" names it).',
      vanilla: "Mojang's art, identical by content hash to the PrismarineJS/minecraft-assets mirror.",
      'third-party': 'Made by someone else under an open license ("license" names it, "from" says where).',
      'vanilla-derived': 'Made by a script from vanilla files.',
      'unknown-modified': 'Named like a vanilla texture but changed or from another version; not yet confirmed.',
      unknown: 'Not yet confirmed.',
    },
    folders: FOLDER_RULES,
    entries,
  };
  writeFileSync(OUT, `${JSON.stringify(doc, null, 2)}\n`);
  const counts = Object.fromEntries(order.map(s => [s, entries.filter(e => e.source === s).reduce((n, e) => n + e.files.length, 0)]));
  const folderCount = files.length - loose.length;
  console.log(`${files.length} files: ${JSON.stringify(counts)}, plus ${folderCount} under folder rules`);
}

main().catch(err => { console.error(err.message); process.exit(1); });
